const sourceCardsV86={"O043":{"heading":"Persiska imperier: flera riken, inte ett enda","theme":"Riken och stormakter","summary":"Det akemenidiska Perserriket byggdes från mitten av 500-talet f.Kr. till ett enormt imperium under Kyros II, Kambyses II och Dareios I. Det omfattade vid olika tider bland annat Anatolien, Egypten, Levanten, Mesopotamien, Iran och områden mot Indusdalen och Centralasien. Administrativa system, vägnät och satrapier band samman skilda samhällen.","context":"Erövringen av Babylon 539 f.Kr. ändrade förutsättningarna för judiska grupper efter den babyloniska exilen. Persiskt styre är en viktig ram för bland annat Esra, Nehemja och senare tempelhistoria.","impact":"Perserrikets flerspråkiga förvaltning, vägnät och imperiala maktutövning skapade sammanlänkade nätverk från Medelhavet till Centralasien.","limits":"Originalposten 550 f.Kr.–651 e.Kr. sammanför flera skilda persiska dynastier, bland annat akemenider och senare sasanider. Det akemenidiska väldet slutade omkring 330 f.Kr. En enda lång stapel får inte behandlas som samma stat eller samma territorium under hela perioden.","sources":[{"name":"Metropolitan Museum – The Achaemenid Persian Empire (550–330 BC)","url":"https://www.metmuseum.org/ja/essays/the-achaemenid-persian-empire-550-330-b-c","type":"Museiessä","supports":"Utsträckning, expansion, Kyros, Dareios och Alexander","verified":"2026-10-12"},{"name":"Metropolitan Museum – Cyrus Cylinder and Ancient Persia","url":"https://www.metmuseum.org/exhibitions/listings/2013/cyrus-cylinder","type":"Museiutställning","supports":"Babylon 539 f.Kr. och dess kontext","verified":"2026-10-12"}]},"O044":{"heading":"Romarriket – republiken, kejsartiden och rikets omvandling","theme":"Riken och stormakter","summary":"Den romerska staten växte ur stadsstaten Rom och den romerska republiken. Från Augustus regeringstid, med början 27 f.Kr., brukar man tala om principatet och kejsartiden. Romersk makt kom att prägla Medelhavets lagar, vägar, städer och handel.","context":"Judeen stod under romersk dominans från 63 f.Kr., före den traditionella startpunkten för kejsartiden. Jesus, Paulus och de äldsta kristna gemenskaperna hör hemma i denna värld.","impact":"Den romerska förvaltningen och transportinfrastrukturen påverkade migration, handel, stadsliv och hur idéer spreds. Östrom/Bysans fortsatte efter Västroms politiska sammanbrott.","limits":"27 f.Kr.–476 e.Kr. avser normalt kejsartidens början och västromerska rikets traditionella slut; det är inte hela den romerska civilisationens eller östromerska statens livslängd. Exakt maximalt territorium varierar med valt år.","sources":[{"name":"World History Encyclopedia – Roman Empire","url":"https://www.worldhistory.org/Roman_Empire/","type":"Historisk översikt","supports":"Augustus, romersk expansion, 476 och fortsättning i öst","verified":"2026-10-12"}]},"O048":{"heading":"Peloponnesiska kriget (431–404 f.Kr.)","theme":"Krig och maktförändring","summary":"Ett omfattande krig mellan Aten, Sparta och deras respektive allierade stadsstater. Rivaliteten mellan Atens sjövälde och Spartas landbaserade makt bidrog till konflikten. Kriget utkämpades även långt från själva Peloponnesos, bland annat i Sicilien.","context":"Aten var en demokratisk stadsstat men styrde också ett omfattande sjöförbund. Spartanernas oro för Atens växande makt samverkade med konflikter mellan allierade. Thukydides beskrev delar av kriget som samtida observatör och deltagare.","impact":"Aten förlorade sin ledande ställning efter nederlaget 404 f.Kr. Kriget visar hur stormaktsrivalitet, allianser, epidemier och ekonomiska resurser kan forma en längre konflikt. Persiskt ekonomiskt stöd till Sparta spelade en roll i slutskedet.","limits":"431–404 f.Kr. avser det krig som vanligen menas med ”Peloponnesiska kriget”. En tidigare konflikt ibland benämnd första peloponnesiska kriget utspelade sig ungefär 460–446/445 f.Kr. Thukydides skildring är en central men inte komplett och inte neutral berättelse.","sources":[{"name":"World History Encyclopedia – Peloponnesian War","url":"https://www.worldhistory.org/Peloponnesian_War/","type":"Historisk översikt","supports":"Orsaker, 431–404 f.Kr. och förlopp","verified":"2026-10-12"},{"name":"World History Encyclopedia – Thucydides","url":"https://www.worldhistory.org/timeline/Thucydides/","type":"Källhistorisk översikt","supports":"Thukydides och hans ofullbordade verk","verified":"2026-10-12"}]},"O049":{"heading":"De puniska krigen – Rom mot Kartago","theme":"Krig och maktförändring","summary":"Tre krig mellan Rom och Kartago: 264–241, 218–201 och 149–146 f.Kr. Striden gällde kontroll över handelsvägar, territorier och politisk makt i västra Medelhavet. Hannibals fälttåg under det andra kriget är ett av antikens mest kända.","context":"Kartago var ett feniciskt grundat handelscentrum i Nordafrika med ett starkt maritimt nätverk. Rom expanderade utanför Italien under konflikterna.","impact":"Rom segrade och stärkte sitt övertag i västra Medelhavet. Kartago förstördes 146 f.Kr., men dess handel, kultur och den längre relationen till Rom kan inte reduceras till endast detta slut.","limits":"Originalets sammanhängande intervall 264–146 f.Kr. är en samlingsrubrik. Det pågick inte ett oavbrutet krig under hela denna tid.","sources":[{"name":"World History Encyclopedia – Punic Wars","url":"https://www.worldhistory.org/Punic_Wars/","type":"Historisk översikt","supports":"Tre skilda krig, årtal och följder","verified":"2026-10-12"}]},"O050":{"heading":"Hundraårskriget mellan England och Frankrike","theme":"Krig och maktförändring","summary":"En lång följd av krig och vapenvilor, vanligen daterad 1337–1453. Konflikterna kretsade kring feodala rättigheter, den engelska kungens anspråk på den franska kronan och kontrollen över områden på kontinenten.","context":"Striderna utspelade sig bland annat i Akvitanien, Normandie och norra Frankrike. Slag som Crécy och Azincourt följdes av nya maktskiften, bland annat under Karl VII och Jeanne d’Arc.","impact":"Kriget påverkade beskattning, krigföring, monarkiernas makt och hur England och Frankrike utvecklades. Den franska kronan stärkte slutligen sin kontroll över stora delar av Frankrike.","limits":"”Hundraårskriget” var inte 116 år av ständiga strider. Rubriken är en efterhandsbeteckning för flera faser.","sources":[{"name":"World History Encyclopedia – Hundred Years’ War","url":"https://www.worldhistory.org/Hundred_Years%27_War/","type":"Historisk översikt","supports":"Periodens konflikter, huvudorsaker och avslut","verified":"2026-10-12"}]},"O051":{"heading":"Trettioåriga kriget – religion och europeisk maktpolitik","theme":"Krig och maktförändring","summary":"Kriget 1618–1648 började i det Tysk-romerska riket med starka konfessionella motsättningar men växte till en bred europeisk maktkamp. Flera stater, bland annat Sverige och Frankrike, ingrep.","context":"Upproret i Böhmen och defenestrationen i Prag 1618 följdes av skiftande allianser. Under kriget spelade både religiös tillhörighet, dynastiska intressen och kontroll över territorier stor roll.","impact":"Kriget bidrog till omfattande förstörelse, fördrivning och befolkningsförluster i delar av Centraleuropa. Westfaliska freden 1648 innebar stora diplomatiska omförhandlingar.","limits":"Det är missvisande att kalla hela kriget enbart ett katolsk-protestantiskt religionskrig. Uppgifter om sammanlagda dödstal och om fredens roll för ”moderna stater” måste behandlas med försiktighet.","sources":[{"name":"HISTORY – Thirty Years’ War","url":"https://www.history.com/articles/thirty-years-war","type":"Historisk översikt","supports":"Viktiga skeden, maktpolitik och Westfaliska freden","verified":"2026-10-12"}]},"O052":{"heading":"Amerikanska inbördeskriget 1861–1865","theme":"Krig och maktförändring","summary":"Ett inbördeskrig mellan USA:s union och utbrytarstaterna i konfederationen. Slaveriets framtid och expansion var den grundläggande politiska konflikt som drev fram utbrytningen, även om soldater hade skiftande motiv.","context":"Motsättningarna hade byggts upp under decennier genom strider om förbundsmakt, territorial expansion och slaveriet i nya delstater.","impact":"Unionens seger bevarade USA som en stat. Slaveriet avskaffades genom det trettonde tillägget till konstitutionen; samhällskonflikterna om medborgerliga rättigheter fortsatte långt efter kriget.","limits":"Att nämna delstaternas rättigheter utan att koppla utbrytningen till slaveriets centrala roll ger en missvisande orsakskedja.","sources":[{"name":"U.S. National Park Service – Causes of the Civil War","url":"https://www.nps.gov/civilwar/causes.htm","type":"Nationalparksmyndighet","supports":"Slaveriets centrala roll och andra politiska konflikter","verified":"2026-10-12"},{"name":"U.S. National Park Service – Overview of the Civil War","url":"https://www.nps.gov/civilwar/overview.htm","type":"Nationalparksmyndighet","supports":"Unionen, emancipation och politiska följder","verified":"2026-10-12"}]},"O053":{"heading":"Första världskriget och stormaktssystemets sammanbrott","theme":"Krig och maktförändring","summary":"Första världskriget 1914–1918 blev en storskalig konflikt med frontkrig, koloniala trupper och omfattande civila påfrestningar. Mordet i Sarajevo utlöste juli-krisen, men allianser, nationalism, militarisering och imperiala rivaliteter bidrog till att konflikten spreds.","context":"De krigförande staterna mobiliserade industri, arbetskraft och resurser i en omfattning som förändrade både front och hemmiljö.","impact":"Kriget bidrog till att flera imperier upplöstes och att nya stater och gränser uppstod. Fredsuppgörelserna och efterkrigstidens konflikter blev viktiga delar av bakgrunden till nästa världskrig.","limits":"En enda utlösande händelse förklarar inte hela krigets orsaker; historiker diskuterar olika staters ansvar och konflikternas långsiktiga drivkrafter.","sources":[{"name":"World History Encyclopedia – The Causes of WWI","url":"https://www.worldhistory.org/article/2723/the-causes-of-wwi/","type":"Historisk analys","supports":"Orsaker, allianser och Sarajevo","verified":"2026-10-12"},{"name":"Imperial War Museums – 4 August 1914 factsheet","url":"https://www.iwm.org.uk/sites/default/files/press-release/4_August_1914_Factsheet.pdf","type":"Museifaktablad","supports":"Allianser och krigsutbrottet 1914","verified":"2026-10-12"}]},"O054":{"heading":"Andra världskriget och dess globala konsekvenser","theme":"Krig och maktförändring","summary":"Andra världskriget 1939–1945 omfattade flera sammankopplade krigsskådeplatser. Nazitysklands angrepp på Polen i september 1939 brukar anges som början på kriget i Europa. I Asien hade Japans krig i Kina pågått sedan tidigare.","context":"Nazistisk expansionspolitik, fascistisk och militaristisk maktutövning, mellankrigstidens kriser samt andra internationella spänningar bidrog till upptrappningen.","impact":"Kriget orsakade massdöd och omfattande förstörelse, och Förintelsen genomfördes i dess kontext. Efteråt växte en ny internationell ordning fram med FN, avkolonisering och skärpt stormaktsmotsättning.","limits":"1939 som startår gäller det vanliga europeiska ramverket. En global berättelse måste också rymma tidigare krig i Asien. Förintelsen får inte reduceras till ett allmänt ”krigsoffer”.","sources":[{"name":"U.S. Holocaust Memorial Museum – World War II in Europe","url":"https://encyclopedia.ushmm.org/content/en/article/world-war-ii-in-europe","type":"Museiuppslagsverk","supports":"Krigets början i Europa och Förintelsens sammanhang","verified":"2026-10-12"},{"name":"World History Encyclopedia – Causes of WWII","url":"https://www.worldhistory.org/article/2409/the-causes-of-wwii/","type":"Historisk analys","supports":"Politiska orsaker och mellankrigstidens kriser","verified":"2026-10-12"}]},"O055":{"heading":"Cheopspyramiden och Egyptens gamla rike","theme":"Byggnadsverk och arkeologi","summary":"Cheopspyramiden i Giza byggdes under Egyptens fjärde dynasti som ett kungligt gravmonument. Den hör till ett större landskap av pyramider, tempel, gravar och anläggningar som visar det gamla rikets politiska organisation och begravningsföreställningar.","context":"Kungamakt, administration, transporter, stenbearbetning och en omfattande arbetsorganisation gjorde monumentet möjligt. Nilens geografi var central för befolkning och försörjning.","impact":"Gizakomplexet har blivit ett viktigt arkeologiskt vittnesbörd om egyptisk teknik, kunglig ideologi och långvariga religiösa traditioner.","limits":"Året 2560 f.Kr. i originaltabellen är en ungefärlig kronologisk placering, inte ett säkert exakt byggår. Moderna hypoteser om byggmetoder är inte alla lika väl belagda.","sources":[{"name":"UNESCO – Memphis and its Necropolis: Pyramid Fields","url":"https://whc.unesco.org/en/list/86/","type":"Världsarvsunderlag","supports":"Pyramidernas sammanhang och platsens arkeologi","verified":"2026-10-12"},{"name":"Metropolitan Museum – Egypt in the Old Kingdom","url":"https://www.metmuseum.org/it/essays/egypt-in-the-old-kingdom-ca-2649-2150-b-c","type":"Museiessä","supports":"Gamla rikets historiska och kulturella sammanhang","verified":"2026-10-12"}]},"O057":{"heading":"Kinesiska muren – flera epokers försvarsanläggningar","theme":"Byggnadsverk och arkeologi","summary":"Kinesiska muren är inte ett enskilt byggprojekt. Olika kinesiska stater och dynastier anlade, förband och förnyade försvarslinjer under mer än två tusen år. Många av de mest kända muravsnitten i sten och tegel hör till Mingdynastin.","context":"Befästningarna förhöll sig till varierande gräns- och maktrelationer mellan jordbrukssamhällen, steppriken och regionala makter.","impact":"Murens olika delar visar hur militär strategi, arbetsorganisation och gränsförvaltning utvecklades över tid.","limits":"Tidsintervallet -700 till 1600 i originalfilen är en förenklad samlingsetikett. Murens sträckning, material och funktion varierar avsevärt mellan epoker.","sources":[{"name":"UNESCO – The Great Wall","url":"https://whc.unesco.org/en/list/438","type":"Världsarvsunderlag","supports":"Olika byggfaser, Qin- och Mingperioderna","verified":"2026-10-12"}]},"O061":{"heading":"Göbekli Tepe – monument och ritual före städerna","theme":"Byggnadsverk och arkeologi","summary":"Göbekli Tepe ligger i sydöstra Anatolien och omfattar monumentala anläggningar från förkeramiskt neolitikum omkring 9600–8200 f.Kr. Stora T-formade stenpelare, ofta med djurreliefer, uppfördes av grupper som befann sig i omvandlingen från jägar-samlarliv mot allt mer bofasta samhällen.","context":"Platsen är viktig för att visa organiserat monumentbyggande långt före de klassiska städerna och de första skrivna religionskällorna.","impact":"Fynden nyanserar föreställningen att omfattande ritualplatser måste ha förutsatt redan etablerade stadsstater och statsmakt.","limits":"Det går inte att identifiera en säker religion eller en enda funktion för alla byggnader. Ingen direkt historisk koppling till Bibelns Eden kan beläggas.","sources":[{"name":"UNESCO – Göbekli Tepe","url":"https://whc.unesco.org/en/list/1572/","type":"Världsarvsunderlag","supports":"Datering, byggnadernas karaktär och försiktig tolkning","verified":"2026-10-12"}]},"H037":{"heading":"Senbronsålderns Kanaan","theme":"Israel och Juda – arkeologi och text","summary":"Det område som senare bibeltexter kallar Kanaan bestod under senare delen av andra årtusendet f.Kr. av stadsstater i politisk relation till Egypten.","context":"Det egyptiska väldets diplomatiska korrespondens ger ett samtida perspektiv på stadsfurstar och konflikter.","impact":"Visar att senare berättelser om ett entydigt erövrat land måste prövas mot en mycket mer sammansatt regional historia.","limits":"Tidsintervallet avser en historisk miljö, inte ett enhetligt administrativt system eller ett exakt början- och slutdatum.","sources":[{"name":"Metropolitan Museum – Egypt in the New Kingdom","url":"https://www.metmuseum.org/toah/hd/nking/hd_nking.htm","type":"Museum/forskningspublikation","supports":"Egyptens nya rike och politiska kontaktnät","verified":"2026-10-12"}]},"H038":{"heading":"Jeriko: arkeologiska lager och biblisk berättelse","theme":"Israel och Juda – arkeologi och text","summary":"Utgrävningar visar bronsåldersförstörelse vid Jeriko, men dateringen, platsens bosättningsfaser och relationen till Josuaboken diskuteras.","context":"Josua 6 beskriver en dramatisk erövring. Arkeologiska dateringar av Tell es-Sultan måste utgå från stratigrafi, keramik och naturvetenskaplig provtagning, inte från berättelsens kronologi.","impact":"Ett konkret exempel på skillnaden mellan textens anspråk och vad en fyndplats kan visa.","limits":"Det valda intervallet är en ungefärlig arkeologisk referenspunkt för en bronsåldersförstörelse. Det får inte behandlas som Josuas historiskt belagda erövringsår; olika tolkningar finns.","sources":[{"name":"Forskningsartikel – Jericho archaeology and Joshua","url":"https://www.mdpi.com/2077-1444/14/6/796","type":"Museum/forskningspublikation","supports":"Redovisar dateringsdebatten och motsatta tolkningar","verified":"2026-10-12"}]},"H039":{"heading":"Filisteiska kustsamhällen","theme":"Israel och Juda – arkeologi och text","summary":"Nya materiella kulturmönster uppträder längs södra Levantens kust vid övergången från brons- till järnålder.","context":"Filisteiska städer såsom Ashkelon, Ashdod och Ekron utvecklades i regionala nätverk under järnåldern.","impact":"En viktig del av bakgrunden till senare berättelser om Israels relation till kuststäderna.","limits":"Begreppet filistéer täcker skiftande samhällen och befolkningsprocesser. Perioden är grov och validerar inte enskilda gestalter i Domarboken.","sources":[{"name":"Metropolitan Museum – Philistines","url":"https://resources.metmuseum.org/resources/metpublications/pdf/Assyria_to_Iberia_Art_and_Culture_in_the_Iron_Age.pdf","type":"Museum/forskningspublikation","supports":"Filisteisk materialkultur och tidig järnålder","verified":"2026-10-12"}]},"H040":{"heading":"Mesha-stelen: Moabs egen historieskrivning","theme":"Israel och Juda – arkeologi och text","summary":"Den moabitiska kungainskriften nämner Israel och hur kung Mesha återtog territorier.","context":"Inskriften är ett självständigt historiskt vittne från 800-talet f.Kr. som kan jämföras med 2 Kung 3.","impact":"Gör det möjligt att jämföra två politiska/religiösa perspektiv på konflikter i regionen.","limits":"Kungliga segertexter är inte neutrala krönikor. Likheter med 2 Kungaboken innebär inte att varje detalj kan bekräftas.","sources":[{"name":"Louvre – Mesha Stele (AO 5066)","url":"https://collections.louvre.fr/en/ark%3A/53355/cl010120339","type":"Museum/forskningspublikation","supports":"Föremål, datering ca 830–805 f.Kr. och inskriftens innehåll","verified":"2026-10-12"}]},"H041":{"heading":"Tel Dan: inskriften och den dynastiska beteckningen","theme":"Israel och Juda – arkeologi och text","summary":"En arameisk kunglig segertext på basaltfragment nämner enligt den vedertagna läsningen ”Davids hus”.","context":"Detta är ett oberoende inskriftsvittne till hur ett judiskt kungahus betecknades under 800-talet f.Kr.","impact":"Ett centralt fynd i debatten om Juda, dynastins minne och regional kungamakt.","limits":"Inskriften är yngre än Davids traditionella levnadstid och bevisar inte storleken på ett eventuellt enat kungarike, Salomos tempel eller enskilda bibliska episoder.","sources":[{"name":"The Jewish Museum – Tel Dan Stele","url":"https://thejewishmuseum.org/exhibitions/tel-dan-stele/","type":"Museum/forskningspublikation","supports":"Datering till 800-talet f.Kr. och inskriftens dynastiska formulering","verified":"2026-10-12"}]},"H042":{"heading":"Sanherib: assyriskt och bibliskt perspektiv","theme":"Israel och Juda – arkeologi och text","summary":"Assyriens kung Sanherib förde krig i Juda år 701 f.Kr. och belägrade bland annat Lakish.","context":"Assyriska kungainskrifter och reliefer måste ställas mot 2 Kung 18–19 och Jes 36–37.","impact":"Ett fall där flera typer av belägg kan jämföras om samma konflikt.","limits":"Att flera källor nämner fälttåget betyder inte att de beskriver varje händelse på samma sätt. Bibliska och assyriska förklaringar till Jerusalems öde skiljer sig.","sources":[{"name":"British Museum – Lachish reliefs","url":"https://www.britishmuseum.org/collection/galleries/assyria-lion-hunts","type":"Museum/forskningspublikation","supports":"Assyriska reliefer kopplade till Lakish under Sanherib","verified":"2026-10-12"}]},"H043":{"heading":"Khirbet Qeiyafa: dateringen och statsfrågan","theme":"Kungarikena Israel och Juda – historiska källor","summary":"Fyndet styrker att det fanns en befäst bosättning i den aktuella tiden.","context":"Samuele- och Kungaböckerna skildrar David och Salomo som kungar i en politiskt sammanhållen miljö. En befäst plats har daterats med olivkärnor och keramik. Garfinkel med kollegor ser en tidig judéisk urbanisering omkring 1000 f.Kr.; Finkelstein och Piasetzky ger en bredare datering som även omfattar senare delen av 900-talet.","impact":"Jämför inskrifter och arkeologi med bibelberättelser utan att utjämna skillnader.","limits":"Kol-14 daterar platsens fyndmiljö, inte en viss kungs byggnadsprogram. Garfinkel och Na’aman skiljer sig åt om den politiska tillhörigheten, trots att de diskuterar samma arkeologiska plats.","sources":[{"name":"Hebrew University – Garfinkel m.fl. kol-14-datering","url":"https://cris.huji.ac.il/en/publications/king-davids-city-at-khirbet-qeiyafa-results-of-the-second-radioca/","type":"Museum/forskning","supports":"Analys av olivkärnor och tolkning som tidig judéisk statlig utveckling.","verified":"2026-10-12"},{"name":"Tel Aviv University – Finkelstein och Piasetzky","url":"https://cris.tau.ac.il/en/publications/khirbet-qeiyafa-absolute-chronology/","type":"Museum/forskning","supports":"Metodkritik och bredare kronologisk tolkning av samma plats.","verified":"2026-10-12"},{"name":"Nadav Na’aman – Is Khirbet Qeiyafa a Judahite city?","url":"https://jhsonline.org/index.php/jhs/article/view/29370","type":"Museum/forskning","supports":"En sakkunnig invändning mot att samma fyndplats entydigt kan knytas till Juda eller David; forskningskonflikt, inte odiskutabelt motbevis.","verified":"2026-10-12"}]},"H044":{"heading":"Omri och Samaria: en nordlig kungamakt","theme":"Kungarikena Israel och Juda – historiska källor","summary":"Nordriket Israel hade en välorganiserad kungamakt som erkändes av grannmakter. Samarias funktion som centralt säte är väl belagd över längre tid.","context":"1 Kung 16:21–28 berättar att Omri blev kung och köpte berget där Samaria grundades som huvudstad. Samaria visar monumental bebyggelse och administrativa strukturer från järnåldern. Assyriska traditioner använder beteckningen ”Omris hus” också efter själva dynastins slut.","impact":"Jämför inskrifter och arkeologi med bibelberättelser utan att utjämna skillnader.","limits":"Samariaostrakonen dateras oftast till 700-talet, inte Omris egen regeringstid. De belägger inte i sig Omris grundningshandling.","sources":[{"name":"PLOS ONE – Samariaostrakon och administration","url":"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0227452","type":"Museum/forskning","supports":"Diskuterar Samarias kungliga centrum och daterar de bevarade ostrakonen huvudsakligen till 700-talet.","verified":"2026-10-12"},{"name":"Journal of Near Eastern Studies – omridisk palatsarkitektur","url":"https://www.journals.uchicago.edu/doi/full/10.1086/690651","type":"Museum/forskning","supports":"Arkeologisk tolkning av monumental arkitektur och statsbildning under Omriderna.","verified":"2026-10-12"}]},"H045":{"heading":"Ahab och slaget vid Qarqar: utombiblisk kungabeteckning","theme":"Kungarikena Israel och Juda – historiska källor","summary":"Det är ett oberoende textvittne till nordrikets internationella politiska betydelse på 800-talet f.Kr.","context":"1 Kung 16–22 beskriver Ahab i konflikter med araméer, i relation till Baalskult och berättelserna om profeten Elia. Slaget vid Qarqar nämns inte i Kungaböckerna. Shalmaneser III:s Kurkh-stel berättar om en antiassyrisk koalition vid Qarqar 853 f.Kr. Den traditionellt identifierade ”Ahab av Israel” nämns bland deltagarna; assyrisk militär retorik måste granskas separat.","impact":"Jämför inskrifter och arkeologi med bibelberättelser utan att utjämna skillnader.","limits":"Assyriska siffror för trupper och vagnar kan vara överdrivna. Stelen bekräftar varken episoderna om Elia eller varje uppgift om Ahabs inrikespolitik.","sources":[{"name":"British Museum – Kurkh-stelen","url":"https://www.britishmuseum.org/collection/object/W_1863-0619-2","type":"Museum/forskning","supports":"Daterat kungligt föremål och inskrift från Shalmaneser III:s tid; deltagarnamn kräver texttolkning.","verified":"2026-10-12"}]},"H046":{"heading":"Jehu och den svarta obelisken: tribut år 841","theme":"Kungarikena Israel och Juda – historiska källor","summary":"Den ger en mycket god extern hållpunkt för Jehus relation till Assyrien och visar att assyrisk beteckning för ett rike kunde leva kvar efter dynastibyten.","context":"2 Kung 9–10 skildrar Jehus maktövertagande och våldsamma utrensning av Omris ätt. Shalmaneser III:s svarta obelisk visar tribut och identifierar ett led som Jehu av ”Omris hus” omkring 841 f.Kr.; monumentet restes ett antal år senare.","impact":"Jämför inskrifter och arkeologi med bibelberättelser utan att utjämna skillnader.","limits":"Att scenen enligt inskriften gäller Jehus tribut betyder inte att alla bibelberättelsens motiv eller gärningar är självständigt bekräftade. Kungainskriften är assyrisk propaganda.","sources":[{"name":"British Museum – den svarta obelisken","url":"https://www.britishmuseum.org/collection/object/W_1848-1104-1","type":"Museum/forskning","supports":"Museiföremål med namngiven tribut från Jehu, år 841 f.Kr.; tillverkning omkring 825 f.Kr.","verified":"2026-10-12"}]}};
const sourceCardsV87={"O074":{"heading":"Dumuzi/Tammuz – sorgen över en gud och livet i underjorden","theme":"Död, liv och återkomst","summary":"Dumuzi var en sumerisk gudom kopplad till herdeliv, fruktbarhet och till Inanna. I berättelsen om Inannas nedstigning till underjorden får Dumuzi en central roll som den som måste tillbringa en del av tiden där. Klagosånger över Dumuzi är också en betydelsefull del av den mesopotamiska litteraturen.","context":"Mesopotamiska texter förekommer i flera versioner och tidslager. Det är särskilt viktigt att skilja en myts händelseförlopp, texters bevarade handskrifter och rituella sorgeuttryck. I senare akkadiska miljöer återfinns namnet Tammuz.","impact":"Motiven binder samman förlust, sorg, återvändande och växlingar i naturen. Hesekiel 8:14 nämner kvinnor som begråter Tammuz, vilket gör jämförelsen särskilt relevant för bibelstudier.","limits":"Originalets etikett ”död och återuppståndelse” blir för grov. Dumuzi ska inte utan vidare beskrivas som en historiskt belagd förebild för Jesu kroppsliga uppståndelse. Förlopp och formuleringar varierar mellan versionerna.","parallels":"Hes 8:14 ger en namngiven koppling till Tammuz-kulten. Berättelsen om Inanna/Dumuzi och påskberättelsen har tematiska likheter kring död och liv, men dessa ger inte i sig belägg för direkt textberoende.","assessment":"Direkt biblisk namnhänvisning: stark. Påstående om direkt modell för evangelierna: ej belagt.","sources":[{"name":"Oxford ETCSL – Inanas nedstigning till underjorden","url":"https://etcsl.orinst.ox.ac.uk/cgi-bin/etcsl.cgi?text=t.1.4.1","type":"Primärtextöversättning","supports":"Dumuzi och underjordsmotivet i den sumeriska texten","verified":"2026-10-12"},{"name":"Metropolitan Museum – sumeriska traditioners långa överlevnad","url":"https://www.metmuseum.org/art/collection/search/321910","type":"Museiföremål","supports":"Traditionernas långa handskriftshistoria","verified":"2026-10-12"}]},"O075":{"heading":"Osiris – död, återupplivning och herravälde i dödsriket","theme":"Död, liv och återkomst","summary":"I egyptisk myt mördas Osiris av sin bror Seth. Isis återför honom till liv i den bemärkelsen att hon med magi möjliggör sonen Horus avlelse. Osiris återvänder inte för att leva ett vanligt liv bland människorna utan är därefter härskare i dödsriket.","context":"Myten växte fram inom egyptisk kungateologi, begravningsritual och föreställningar om livet efter döden. Berättelsen finns i olika lager av ikonografi, texter och senare återberättelser, och bör inte pressas in i ett enda årtal.","impact":"Osiris blev en central gestalt i egyptisk begravningskultur och människors föreställningar om dom, förnyelse och hopp om fortsatt liv. Sambandet mellan död och kosmisk ordning är tydligt.","limits":"Att bara säga ”Osiris uppstod” kan vilseleda. En temporär återupplivning och ett fortsatt liv som härskare i underjorden är inte samma berättelse som evangeliernas grav- och uppståndelseskildringar.","parallels":"Jämför temat att döden inte får sista ordet med Nya testamentet. För en genetisk hypotes om direkt kopiering krävs emellertid specifika textliga och historiska kontaktspår som dessa likheter inte etablerar.","assessment":"Osirismytens existens: väl belagd. Direkt kopiering till evangeliernas uppståndelseberättelse: inte belagd.","sources":[{"name":"The Met – Isis och spädbarnet Horus","url":"https://www.metmuseum.org/art/collection/search/545961","type":"Museiföremål","supports":"Osiris död, Isis återupplivning och Horus födelse","verified":"2026-10-12"},{"name":"The Met – Osiris och livet efter döden","url":"https://www.metmuseum.org/exhibitions/listings/2018/nedjemankh-gilded-coffin/exhibition-gallery","type":"Museiessä","supports":"Osiris dödsrikets funktion och egyptisk efterlivstro","verified":"2026-10-12"}]},"O076":{"heading":"Baal, Mot och återkomsten – ugaritisk gudamyt","theme":"Död, liv och återkomst","summary":"I Baalcykeln från Ugarit ställs stormguden Baal mot havets och dödens makter, däribland Mot. Baals frånvaro har samband med torka; när Baal åter träder fram återupprättas ordningen. Rollen som stormgud och gudarnas kung är central.","context":"Ugaritiska kilskriftstavlor från sen bronsålder ger ett ovanligt rikt material om västsemitisk religion. Bibelns Israel växte fram i en kulturell region där stormgudssymbolik och gudaförsamlingar hörde till den religiösa föreställningsvärlden.","impact":"Myten hjälper oss tolka bilder av gudomlig makt över hav, drakar och kaos i vissa gammaltestamentliga poetiska texter. Relationerna bör prövas passage för passage.","limits":"Forskare har tolkat Baals förhållande till döden olika: död och återkomst, symbolisk nedstigning eller en mer komplex texttradition. En säker historisk ”uppståndelse på tredje dagen” finns inte dokumenterad här.","parallels":"Motiv kring gudomlig stormmakt, kaoskamp och kungavälde kan jämföras med Ps 29, Ps 74 och Jes 27. Det är i många fall en närmare kulturhistorisk jämförelse än sena allmänna likheter med Jesu uppståndelse.","assessment":"Ugaritisk texttradition och motivparalleller: väl belagda. Den exakta tolkningen av Baals död: omdiskuterad.","sources":[{"name":"The Met – The Gods and Goddesses of Canaan","url":"https://www.metmuseum.org/essays/the-gods-and-goddesses-of-canaan","type":"Museiessä","supports":"Baalcykelns motiv och ugaritisk gudavärld","verified":"2026-10-12"},{"name":"Cambridge – The Myth of Môt and ʼAlʼeyan Baʻal","url":"https://www.cambridge.org/core/journals/harvard-theological-review/article/abs/myth-of-mot-and-aleyan-baal/7908DB252B858021274266BAE337A5D4","type":"Forskningsartikel","supports":"Klassisk forskningsdiskussion om Baal och Mot","verified":"2026-10-12"}]},"O077":{"heading":"Adonis – död, årstider och berättelsen om två gudinnor","theme":"Död, liv och återkomst","summary":"Adonis är en mytisk gestalt i grekisk och närorientalisk tradition, nära förbunden med Afrodite och Persefone. Varianter av myten berättar om hans död och om att han tillbringar tid i skilda gudinnors sfärer.","context":"Berättelsernas former och funktioner varierar från religiösa ritualer till konst och poesi. I grekisk ikonografi förekommer motiv om hans död och återvändande i förbindelse med vegetation och årstidsväxling.","impact":"Adonistraditionerna visar hur naturens cykler, sorg och död kunde gestaltas religiöst. De är jämförelsematerial till bredare antika liv-död-motiv, inte en färdig kronologisk modell för evangelierna.","limits":"Det går inte att påstå att varje variant har samma uppståndelsesyn eller att ett bestämt äldre textvittne innehåller alla senare motiv.","parallels":"Det finns motivlikheter med andra traditioner om död och återkomst, men detta räcker inte som belägg för att evangeliernas berättelser lånats från Adonis.","assessment":"Grekisk Adonistradition: belagd. Specifikt direkt beroende till NT: ej belagt.","sources":[{"name":"The Met – loutrophoros med Adonismotiv","url":"https://www.metmuseum.org/art/collection/search/248580","type":"Museiföremål","supports":"Antik ikonografi och tolkning av årstidsmotiv","verified":"2026-10-12"}]},"O078":{"heading":"Mithras – romersk mysteriekult, inte dokumenterad uppståndelse","theme":"Mysteriekulter och religiösa måltider","summary":"I romersk mithraism dyrkades en gud som ofta avbildas när han dödar en tjur. Kulten utövades i särskilda samlingsrum, mithreer, och omfattade initiering samt gemensamma måltider. Mycket är känt från arkeologi, men få berättande källor finns bevarade.","context":"Romersk mithraism utvecklades under kejsartiden. Sambandet med den äldre iranska gudomen Mithra är forskningsmässigt omdiskuterat. Bildmotiv som födelse ur klippa, tjurdödande och bankett med Sol är belagda.","impact":"Mithraism ger jämförelsematerial till romerska kulters grupptillhörighet, ritualer och symbolik. Den ger inte automatiskt kunskap om kristendomens ursprung.","limits":"Originalpostens ord ”frälsare, måltid, uppståndelse” blandar belagda, tolkningsbara och obelagda utsagor. Mithras egen död och uppståndelse är inte dokumenterad i de bevarade romerska källorna.","parallels":"Rituella måltider kan jämföras som socialt fenomen med tidigkristen gemenskap. Att identifiera en direkt kopia av nattvarden eller Jesu uppståndelse saknar tillräcklig evidens.","assessment":"Måltider och tjurdödande: väl belagda. Mithras uppståndelse: saknar belägg.","sources":[{"name":"The Met – Mystery Cults in the Greek and Roman World","url":"https://www.metmuseum.org/ja/essays/mystery-cults-in-the-greek-and-roman-world","type":"Museiessä","supports":"Mithraisk organisation, bevarat källäge och romersk miljö","verified":"2026-10-12"},{"name":"The Met – bronze plaque of Mithras slaying the bull","url":"https://www.metmuseum.org/art/collection/search/256570","type":"Museiföremål","supports":"Tjurdödandet och daterad romersk bildkälla","verified":"2026-10-12"}]},"O081":{"heading":"Horus – gudabarn, kungamakt och Isis omsorg","theme":"Gudabarn och födelsemotiv","summary":"Horus är i en av sina viktiga former son till Isis och Osiris. Enligt Osirismyten gör Isis det möjligt att avla Horus efter Osiris död och skyddar sonen från Seth. Horus knyts nära till den regerande faraon.","context":"Egyptiska religiösa berättelser, statyetter och bildprogram visar Isis med Horus som barn och Horus som rättmätig kung. Gestalten har flera egyptiska former och funktioner över lång tid.","impact":"Horusbilderna visar idéer om gudomlig härkomst, modersomsorg, maktlegitimitet och beskydd. Det finns också långt senare kristna bilder av mor och barn, men bildlikhet ensam fastställer inte beroenderiktning.","limits":"Det är missvisande att utan förbehåll kalla detta ”jungfrufödsel”. Horus blir till i relation till Osiris, även om omständigheterna är extraordinära. Myten motsvarar inte berättelserna om Maria i Matt 1 och Luk 1.","parallels":"Jämförelsen rör gudabarn och moderssymbolik, inte en identisk födelseberättelse. Direkta kopieringspåståenden behöver betydligt starkare bevis.","assessment":"Horus- och Isisikonografi: mycket väl belagd. ”Horus född av jungfru” i kristen bemärkelse: missvisande.","sources":[{"name":"The Met – Isis nursing infant Horus","url":"https://www.metmuseum.org/art/collection/search/545961","type":"Museiföremål","supports":"Isis, Osiris och Horus i egyptiskt källmaterial","verified":"2026-10-12"},{"name":"British Museum – Egyptian gods and goddesses","url":"https://www.britishmuseum.org/learn/schools/ages-7-11/ancient-egypt/ancient-egyptian-gods-and-goddesses","type":"Museiöversikt","supports":"Grundläggande myt och gudarnas funktioner","verified":"2026-10-12"}]},"O083":{"heading":"Perseus – en gudason och en annorlunda mirakulös avlelse","theme":"Gudabarn och födelsemotiv","summary":"I grekisk myt hålls Danaë instängd av sin far, men Zeus når henne i form av ett guldregn. Hon föder hjälten Perseus, som senare bland annat besegrar Medusa.","context":"Myten är gammal och förekommer i antika konstverk. En grekisk vas från omkring 470–460 f.Kr. återger händelser kring Danaë och Perseus; det finns också senare litterära versioner.","impact":"Perseus är ett exempel på att gudomligt faderskap och övernaturliga födelsemotiv var välkända i antikens Medelhavsvärld.","limits":"Uttrycket ”jungfrufödsel” kan missförstås: Danaë blir gravid genom Zeus uppträdande som guldregn. Det är inte samma idé eller narrativa struktur som Matteus och Lukas tillskriver Jesu tillblivelse.","parallels":"Motivlikhet: mänsklig mor och gudomlig far. Ingen belagd enkel härledning från Perseusmyten till evangelierna.","assessment":"Myten och den tidiga ikonografin: belagda. Direkt litterärt beroende i födelseevangelierna: obevisat.","sources":[{"name":"The Met – terracotta stamnos med Danaë och Perseus","url":"https://www.metmuseum.org/art/collection/search/256900","type":"Museiföremål","supports":"Äldre bildvittne och antik berättelseform","verified":"2026-10-12"},{"name":"The Met – Greek Art, Perseus tradition","url":"https://resources.metmuseum.org/resources/metpublications/pdf/Greek_Art_From_Prehistoric_to_Classical.pdf","type":"Museipublikation","supports":"Översikt av myten med äldre traditioner","verified":"2026-10-12"}]},"O084":{"heading":"Dionysos – gud, vin, extas och rituell gemenskap","theme":"Mysteriekulter och religiösa måltider","summary":"Dionysos är en grekisk gud associerad med vin, teater, förvandling, extas och ibland död och nytt liv. Traditioner om hans födelse och följare är mångskiftande; dryckesritualer ingick i en vidare kultisk värld.","context":"I antiken förekom dionysiska processioner, teaterfester och olika kultformer. Senantika bilder och texter kunde också kopplas till kristna symboler, men sådan senare reception får inte förväxlas med ursprungliga bibliska textkällor.","impact":"Dionysos visar hur vin och livsenergi kunde bära religiösa betydelser långt före och samtidigt med den tidiga kristendomen. Det är relevant vid jämförelser med Joh 2 och nattvardsföreställningar.","limits":"Påståenden om exakt tolv lärjungar, nattvard i kristen form och en identisk uppståndelsehistoria är inte dokumenterade som ett enhetligt Dionysosmotiv.","parallels":"Vinets symbolik och rituell gemenskap är jämförbara temaområden. Direkta kopieringshypoteser kräver närläsning och daterade källor.","assessment":"Vinsymbolik och kult: belagt. Påstådda exakta Jesuparalleller: i flera fall obelagda.","sources":[{"name":"The Met – Mystery Cults in the Greek and Roman World","url":"https://www.metmuseum.org/ja/essays/mystery-cults-in-the-greek-and-roman-world","type":"Museiessä","supports":"Mysteriekulter och kultmiljö","verified":"2026-10-12"},{"name":"The Met – Popular Religion and Byzantine Art","url":"https://www.metmuseum.org/en/essays/popular-religion-magical-uses-of-imagery-in-byzantine-art","type":"Museiessä","supports":"Senare paralleller och reception av dionysiska motiv","verified":"2026-10-12"}]},"O085":{"heading":"Dionysos och ”tolv följeslagare” – källkritiskt test","theme":"Gudabarn och födelsemotiv","summary":"Dionysos avbildas och berättas ofta tillsammans med ett följe, ibland kallat thiasos, av exempelvis maenader, satyrer och andra gestalter. Det är inte samma sak som en fast namngiven grupp om tolv lärjungar.","context":"Antika kulter och bilder ska beskrivas utifrån daterade källor i stället för efterhandslistor över påstådda likheter med Jesus.","impact":"Detta är en bra fallstudie i hur populärvetenskapliga parallellistor kan skapa en till synes exakt koppling genom att lägga till en siffra som källmaterialet inte stöder.","limits":"Jag har inte funnit säkra antika belägg för att Dionysos konsekvent hade just tolv namngivna lärjungar som motsvarade de tolv apostlarna. Ett avsaknat belägg bör inte omvandlas till ett historiskt påstående.","parallels":"Jämför följeslagarmotivet generellt, men märk just antalet tolv som obelagt i denna kontext.","assessment":"Rituella följen: belagda. Exakt ”tolv apostlar” till Dionysos: inte styrkt i kontrollerade källor.","sources":[{"name":"The Met – Mystery Cults","url":"https://www.metmuseum.org/ja/essays/mystery-cults-in-the-greek-and-roman-world","type":"Museiessä","supports":"Bakgrund till dionysiska kulter och följare","verified":"2026-10-12"}]},"O087":{"heading":"Zoroastrism – kosmisk kamp, dom och judisk apokalyptik","theme":"Kosmisk kamp och vishetstraditioner","summary":"Zoroastrisk religion utvecklade föreställningar om kampen mellan goda och onda krafter och om moralisk dom. En del teman har tydliga jämförelsepunkter med judisk apokalyptisk litteratur och senare kristendom.","context":"Persiskt styre och judiska miljöer möttes under flera århundraden. Samtidigt är bevarade zoroastriska texter skiktade och vissa utförliga formuleringar är mycket senare än tidiga judiska belägg.","impact":"Jämförelsen är viktig för frågorna om ondskans ursprung, änglar, slutlig dom, uppståndelse och världens förnyelse. Den illustrerar också att religiösa idéer utvecklas genom både intern kontinuitet och kulturella kontakter.","limits":"Att datera alla senare zoroastriska föreställningar till 1500 f.Kr. eller påstå att den judiska apokalyptiken rakt av är ett persiskt lån är för tvärsäkert. Forskningsläget är mer nyanserat.","parallels":"Jämför Dan 12, 1 Henok och senare judisk litteratur. Kontakt är historiskt möjlig och påverkan diskuteras, men varje specifikt idéursprung måste argumenteras för.","assessment":"Historisk kontakt och tematiska paralleller: belagda. Exakt beroenderiktning och tidpunkt: omdiskuterade.","sources":[{"name":"Encyclopaedia Iranica – Eschatology i. Zoroastrianism and influence","url":"https://www.iranicaonline.org/articles/eschatology-i/","type":"Forskningsuppslagsverk","supports":"Utveckling av eskatologi och metodsvårigheter vid påverkanshypoteser","verified":"2026-10-12"}]},"O088":{"heading":"Mithraskultens rituella måltid","theme":"Mysteriekulter och religiösa måltider","summary":"Kultdeltagare i romerska mithreer åt tillsammans och delade religiös identitet. Monument och byggnader visar en social och symbolisk måltidsmiljö, ofta kopplad till bilder av Mithras och solguden Sol.","context":"Måltider var centrala i många antika religiösa och sociala gemenskaper. Mötesrummen rymde små grupper och deras bänkar möjliggjorde gemensamma måltider.","impact":"Att två grupper delar måltid som religiös handling visar en jämförbar social funktion, men gör inte de enskilda ritualernas teologi identisk.","limits":"Varken ett exakt nattvardsformulär eller en dokumenterad myt om Mithras död och uppståndelse kan hämtas ur dessa arkeologiska belägg.","parallels":"Jämför 1 Kor 11 och evangeliernas måltidstraditioner på nivån ”gemenskap och ritual”. Påståenden om att nattvarden direkt kopierades från mithraismen är obestyrkta.","assessment":"Gemensamma måltider: väl belagda. Direkt upphov till kristen nattvard: inte visat.","sources":[{"name":"The Met – Eastern Religions in the Roman World","url":"https://www.metmuseum.org/de/essays/eastern-religions-in-the-roman-world","type":"Museiessä","supports":"Mithreernas måltider och bildmotiv","verified":"2026-10-12"},{"name":"The Met – Roman Art (lärarresurs)","url":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","type":"Museipublikation","supports":"Arkeologiska mithreer, bankett med Sol och kultillustrationer","verified":"2026-10-12"}]},"O089":{"heading":"Dionysiska ritualer, vin och påståendet om ”vin som blod”","theme":"Mysteriekulter och religiösa måltider","summary":"Vin har stark ställning i dionysisk religiös kultur. Ett rituellt eller symboliskt bruk av vin kan jämföras med andra antika religiösa måltider, men exakt betydelse varierar med kultplats, text och tid.","context":"Dionysos tillhörde en mångskiftande medelhavsvärld där olika festivaler och kultföreningar utvecklade egna handlingar. Senare kristna och icke-kristna författare kunde se samband och kontraster mellan kultformer.","impact":"Ämnet visar hur symboler för liv, fruktbarhet och gudomlig närvaro kan få olika religiösa tolkningar.","limits":"Originalrubriken ”vin som blod” behöver ett konkret daterat textvittne innan den kan jämföras med nattvardens ord om blodet. Källorna som granskats här stödjer vinsymbolik, men inte en universell dionysisk formel identisk med kristen nattvard.","parallels":"Jämför vinsymbolik och religiösa sammankomster, men undvik påståenden om ordagrann kopiering utan primärkälla.","assessment":"Vinets religiösa funktion: belagd. Exakt rituell ”vin = blod”-formel som direkt förebild: inte styrkt.","sources":[{"name":"The Met – Mystery Cults in the Greek and Roman World","url":"https://www.metmuseum.org/ja/essays/mystery-cults-in-the-greek-and-roman-world","type":"Museiessä","supports":"Olika mysteriekultiska praktiker","verified":"2026-10-12"},{"name":"The Met – Byzantinsk konst och Dionysos","url":"https://www.metmuseum.org/en/essays/popular-religion-magical-uses-of-imagery-in-byzantine-art","type":"Museiessä","supports":"Senare tolkningshistoriska kristna/dionysiska jämförelser","verified":"2026-10-12"}]},"O090":{"heading":"Amenemope och Ordspråksboken – konkret vishetsparallell","theme":"Kosmisk kamp och vishetstraditioner","summary":"Den egyptiska vishetsläran ”Undervisning av Amenemope” innehåller råd om socialt beteende, självbehärskning och rättvisa. Flera formuleringar och ordningsmönster kan jämföras konkret med Ordspråksboken 22:17–24:22.","context":"Den egyptiska texten finns belagd på papyrus, bland annat i British Museum. Jämförelsen gäller en specifik litterär vishetstradition som cirkulerade i den forntida Främre Orienten.","impact":"Detta är ett starkare exempel på möjlig litterär kontakt än allmänna likheter mellan myter om död och liv. Det hjälper oss förstå hur biblisk vishet kan ha formats i en internationell skriftskolad miljö.","limits":"Det finns forskningsdiskussion om hur nära beroendet är, vilka mellanled som funnits och när traditionerna sammanställdes. Säg därför hellre ”påfallande textparalleller” än en obetingad kopieringskedja.","parallels":"Konkreta vishetsparalleller till Ord 22–24 ger en god grund för diskussion om litterär påverkan.","assessment":"Egyptisk text och specifika paralleller: väl belagda. Exakt överföringsväg: diskuteras.","sources":[{"name":"British Museum – Teaching of Amenemope, papyrus EA10474","url":"https://www.britishmuseum.org/collection/object/Y_EA10474-5","type":"Museiföremål","supports":"Bevarat textvittne och forskningsreferenser","verified":"2026-10-12"},{"name":"British Museum – Teaching of Amenemope, papyrusfragment","url":"https://www.britishmuseum.org/collection/object/Y_EA10474-4","type":"Museiföremål","supports":"Primärkällans existens och karaktär","verified":"2026-10-12"}]},"O091":{"heading":"Babylonisk teodicidialog och Jobs bok","theme":"Kosmisk kamp och vishetstraditioner","summary":"Den så kallade Babyloniska teodicidialogen är en akkadisk vishetstext där en lidande människa samtalar med en vän om orättvisa, gudarnas ordning och det mänskliga livet. Den kan jämföras med Jobsbokens diskussion om oförtjänt lidande.","context":"Liknande litterära former uppstod i Mesopotamien långt före den slutliga utformningen av Jobs bok. Överlevande lertavlor och senare textstudier gör det möjligt att jämföra både tema och dialogform.","impact":"Jämförelsen visar att Jobsbokens frågor hörde till ett bredare forntida intellektuellt samtal om gudomlig rättvisa. Den hjälper också tydliggöra vad som är särpräglat i Jobs dramatiska uppbyggnad.","limits":"Likhet i genre och problemställning bevisar inte att Jobs författare hade just denna text framför sig. Den aktuella textens datering, bevarade fragment och författarskap kräver särskild granskning.","parallels":"Jämför Job 3–42 med dialogens frågor om lidande. En forskningsmässigt relevant litterär genreparallell, utan påvisad direkt kopiering.","assessment":"Både textvittnen och litterära släktskap: väl dokumenterade. Direkt beroende: osäkert.","sources":[{"name":"Yale – Cuneiform Commentaries Project, Theodicy","url":"https://ccp.yale.edu/P404917","type":"Källkatalog","supports":"Lertavlans katalogdata och kritisk utgåva","verified":"2026-10-12"},{"name":"Oxford – Carol Newsom, Wisdom Dialogue and Job","url":"https://academic.oup.com/book/3694/chapter-abstract/145065472","type":"Forskningsbok","supports":"Forskningsjämförelse av dialoggenren","verified":"2026-10-12"}]}};
const primaryTextsV88={"O074":{"topic":"Dumuzi och Inannas nedstigning","genre":"Direkt textkontakt och motivjämförelse","claim":"I Inannas nedstigning lämnas Dumuzi till underjordens makter. Hesekiel beskriver sorg över Tammuz.","limit":"De två källställena belägger olika text- och rituella sammanhang; de bevisar ingen generell lära om återuppståndelse jämförbar med evangelierna.","passages":[{"reference":"ETCSL 1.4.1, rader 354–358","label":"Inannas nedstigning: Dumuzi överlämnas","url":"https://etcsl.orinst.ox.ac.uk/cgi-bin/etcsl.cgi?text=t.1.4.1","what":"Inanna överlämnar Dumuzi till underjordens demoner.","status":"Textställe kontrollerat","kind":"Antik text i översättning"},{"reference":"Hesekiel 8:14","label":"Sorg över Tammuz","url":"https://www.bible.com/sv/bible/417/EZK.8.B2000D","what":"Profeten beskriver kvinnor som sörjer Tammuz vid tempelingången.","status":"Textställe kontrollerat","kind":"Bibeltext","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 8 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/EZK.8.B2000D"}]}],"related":["O075","O076"]},"O075":{"topic":"Osiris hos Plutarchos","genre":"Sent antikt vittnesmål","claim":"Osiris död och Isis sökande beskrivs i en grekisk-romersk framställning av äldre egyptiskt stoff.","limit":"Plutarchos är en sen antik återberättare, inte ett samtida vittne till Egyptens gamla rike; hans kapitel ska inte ensam datera mytens ursprung.","passages":[{"reference":"Plutarchos, De Iside et Osiride §§13–19","label":"Osiris, Isis och Seth/Tyfon","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A2008.01.0239%3Asection%3D13","what":"Berättelse om Osiris öde, kistan och Isis sökande.","status":"Textställe kontrollerat","kind":"Antik återberättelse (sent vittne)"}],"related":["O081"]},"O076":{"topic":"Baals kamp mot Mot","genre":"Textställe identifierat; översättning kräver fortsatt kontroll","claim":"Baalcykelns sena tavlor behandlar Baals möte med Mot och hans öde.","limit":"KTU-numren är exakta textlokatorer, men utan en öppet tillgänglig kritisk text/översättning har vi inte kontrollerat enskilda radnummer. Därför markeras inte detta som full primärtextkontroll.","passages":[{"reference":"KTU 1.5–1.6 (särskilt 1.6)","label":"Baal och Mot i den ugaritiska Baalcykeln","url":"https://en.wikipedia.org/wiki/Baal_Cycle","what":"Identifierar tavlorna om konflikten. Kontrollera i kritisk utgåva för radnivå.","status":"Textlokator verifierad, översättning ej kontrollerad","kind":"Sekundär vägledning till primärtext"}],"related":["O074"]},"O078":{"topic":"Mithras och den rituella måltiden","genre":"Kristen antik polemik","claim":"Justinus Martyren nämner bröd och en bägare vatten i mithraiska initiationsriter.","limit":"Justinus skriver polemiskt från ett kristet perspektiv. Texten belägger hans beskrivning av riten, inte att Mithras dog och uppstod eller att måltiderna var identiska.","passages":[{"reference":"Justinus Martyren, Första apologin 66","label":"Bröd och vatten i Mithrasriter","url":"https://www.newadvent.org/fathers/0126.htm","what":"Justinus polemiserar mot en rite med bröd och vatten.","status":"Textställe kontrollerat","kind":"Antik kristen partsutsaga"}],"related":["O088"]},"O081":{"topic":"Horus och avlelsens berättelser","genre":"Antikt vittne och ikonografi","claim":"Plutarchos återger traditioner om Isis, Osiris och Horus, men är en sen källa.","limit":"Berättelsen handlar inte om den evangeliska jungfrufödselns formulering och behöver jämföras med äldre egyptiska källor separat.","passages":[{"reference":"Plutarchos, De Iside et Osiride §§12–19","label":"Horus och Osiris inom Isis-traditionen","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A2008.01.0239%3Asection%3D13","what":"Sent vittnesmål om Isis, Osiris och deras familjekrets.","status":"Textställe kontrollerat","kind":"Antik återberättelse (sent vittne)"}],"related":["O075"]},"O083":{"topic":"Perseus födelse","genre":"Direkt läsbart grekiskt textställe","claim":"Apollodoros återger motivet att Zeus närmar sig Danaë som ett regn av guld.","limit":"Motivet är ett mytologiskt avlelseunder; det motsvarar inte evangeliernas ordval eller teologiska förståelse av Jesu födelse.","passages":[{"reference":"Apollodoros, Bibliotheke 2.4.1","label":"Danaë, Zeus och Perseus","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0022%3Atext%3DLibrary%3Abook%3D2%3Achapter%3D4","what":"Berättelsen om hur Danaë föder Perseus och den alternativa traditionen om Proitos.","status":"Textställe kontrollerat","kind":"Antik text i översättning"}],"related":["O081"]},"O084":{"topic":"Dionysos, vinet och gudomens identitet","genre":"Grekisk hymnlitteratur","claim":"Homeriska hymn 7 beskriver hur vin flyter fram på Dionysos skepp och hur växter slår ut.","limit":"Hymnen belägger ett vinunder, inte att Dionysos instiftade nattvarden eller hade tolv lärjungar.","passages":[{"reference":"Homeriska hymn 7, rader 33–42","label":"Vin och vinrankor på skeppet","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0138%3Ahymn%3D7","what":"Vin strömmar fram och vinrankor växer på skeppet där Dionysos tillfångatagits.","status":"Textställe kontrollerat","kind":"Antik text i översättning"}],"related":["O085","O089"]},"O085":{"topic":"Dionysos och påståendet om tolv följeslagare","genre":"Kontroll av negativt påstående","claim":"Det finns ett välbelagt vinunder i Homeriska hymn 7 men ingen grupp om tolv följeslagare i just denna passage.","limit":"Frånvaro i en hymns avsnitt är inte bevis för att motivet saknas i all antik litteratur. En generell slutsats kräver större korpusgenomgång.","passages":[{"reference":"Homeriska hymn 7, rader 1–59","label":"Hymnen om Dionysos och sjörövarna","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0138%3Ahymn%3D7","what":"Avsnittet berättar om sjörövare, en styrman och gudomliga tecken; inte tolv fasta följeslagare.","status":"Textställe kontrollerat","kind":"Antik text i översättning"}],"related":["O084"]},"O087":{"topic":"Zoroastrisk kosmologi och val","genre":"Primärtext med omstridd översättning","claim":"Yasna 30 beskriver två urtida andar och valet mellan bättre och sämre tanke, ord och handling.","limit":"Översättningar skiljer sig på viktiga punkter. Textlikhet med senare judisk apokalyptik bevisar inte en dokumenterad historisk överföring.","passages":[{"reference":"Yasna 30.2–5","label":"De två andarna och det moraliska valet","url":"https://lrc.la.utexas.edu/eieol/aveol/40","what":"Text och akademisk kommentar från University of Texas om gammalavestiskans formuleringar.","status":"Textställe kontrollerat","kind":"Primärtext med språklig kommentar"}],"related":["O076"]},"O088":{"topic":"Mithras och bröd/vatten","genre":"Källkritik av rituell parallell","claim":"Justinus Martyren nämner bröd och vatten i en rite kopplad till Mithras.","limit":"Detta är en kristen polemisk källa, inte en mithraisk handbok. Orden gäller inte vin som blod och visar inget enkelt ursprung för kristen nattvard.","passages":[{"reference":"Justinus Martyren, Första apologin 66","label":"Mithrasrit i kristen redogörelse","url":"https://www.newadvent.org/fathers/0126.htm","what":"Tydligt nämnd bröd- och vattenritual i Justins argument.","status":"Textställe kontrollerat","kind":"Antik kristen partsutsaga"}],"related":["O078"]},"O089":{"topic":"Dionysos och påståendet ”vin som blod”","genre":"Motivprövning","claim":"Homeriska hymn 7 visar ett vinunder och gör det möjligt att kontrollera ett konkret påstående.","limit":"Hymnen säger inte att vinet blir Dionysos blod. Ett sådant påstående behöver en annan identifierad primärkälla innan det kan föras in som faktum.","passages":[{"reference":"Homeriska hymn 7, rader 33–42","label":"Vin på skeppet","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0138%3Ahymn%3D7","what":"Berättelsen gäller vin som strömmar fram och vinrankor som växer.","status":"Textställe kontrollerat","kind":"Antik text i översättning"}],"related":["O084"]},"O090":{"topic":"Amenemope och Ordspråksboken","genre":"Textparallell med forskningsdiskussion","claim":"Ordspråksboken 22:17–23:11 har konkreta likheter med den egyptiska Instruktionen av Amenemope.","limit":"Papyrusen är ett antikt textvittne; museiposten är inte en fullständig översättning. För parallella rader använder vi här en forskningsanalys, och den direkta beroendefrågan bör redovisas med nyanser.","passages":[{"reference":"Ordspråksboken 22:17–23:11","label":"De visas ord","url":"https://www.bible.com/sv/bible/417/PRO.22.B2000D","what":"Biblisk text som jämförs med Amenemope.","status":"Textställe kontrollerat","kind":"Bibeltext","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 22 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/PRO.22.B2000D"},{"label":"Läs kapitel 23 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/PRO.23.B2000D"}]},{"reference":"Amenemope, kap. 1 (4.4–5); jämför Ords 22:22","label":"Förbud mot att förtrycka fattiga","url":"https://www.thetorah.com/article/proverbs-in-egyptian-scribal-style","what":"Forskningsöversikten redovisar numrerade textparalleller mellan två corpora.","status":"Parallellen kontrollerad via forskningsanalys","kind":"Vetenskaplig sekundäranalys med textlokator"},{"reference":"Papyrus British Museum EA 10474","label":"Originalhandskriftens museipost","url":"https://www.britishmuseum.org/collection/object/Y_EA10474-1","what":"Bekräftar ett konkret bevarat textvittne till Amenemopes undervisning.","status":"Textställe kontrollerat","kind":"Museiföremål, inte komplett text"}],"related":["O079","H007"]},"O079":{"topic":"Hammurabis lagar och biblisk rätt","genre":"Direkt lagjämförelse","claim":"Hammurabis lag §196 och 2 Mos 21:23–25 uppvisar en specifik princip om proportionell vedergällning.","limit":"Liknande rättsformuleringar betyder inte automatiskt att ett verk kopierat det andra; de tillhör en bredare antik rättskultur.","passages":[{"reference":"Hammurabis lag §196","label":"Öga för öga – Louvre","url":"https://www.louvre.fr/en/the-code-of-hammurabi","what":"Museet återger §196 och tolkar stelen som ett juridiskt kungamonument.","status":"Textställe kontrollerat","kind":"Antik lagtext via museum"},{"reference":"2 Moseboken 21:23–25","label":"Lex talionis i förbundsboken","url":"https://www.bible.com/sv/bible/417/EXO.21.B2000D","what":"Den bibliska lagens formulering om proportionell vedergällning.","status":"Textställe kontrollerat","kind":"Bibeltext","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 21 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/EXO.21.B2000D"}]}],"related":["O080","O090"]},"O082":{"topic":"Herakles och hjältemotiv","genre":"Grekisk berättartradition","claim":"Apollodoros samlar Herakles prövningar och hans kamp mot omänskliga motståndare.","limit":"Herakles uppdrag är inte Jesu tolv lärjungar, och en mytologisk hjältecykel är inte samma litterära genre som evangelierna.","passages":[{"reference":"Apollodoros, Bibliotheke 2.5.1–12","label":"Herakles arbeten","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0022%3Atext%3DLibrary%3Abook%3D2%3Achapter%3D5","what":"Berättar om Nemeiska lejonet, hydran och de andra uppdragen.","status":"Textställe kontrollerat","kind":"Antik text i översättning"}],"related":["O086"]},"O086":{"topic":"Herakles tolv arbeten","genre":"Sifferparallell som behöver metod","claim":"Apollodoros beskriver en serie heroiska arbeten som i traditionen kom att räknas som tolv.","limit":"Samma antal i olika traditioner är inte i sig bevis för direkt påverkan och arbetena motsvarar inte Jesu lärjungar.","passages":[{"reference":"Apollodoros, Bibliotheke 2.5.1–12","label":"Tolv arbeten och omräkningen","url":"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0022%3Atext%3DLibrary%3Abook%3D2%3Achapter%3D5","what":"Eurystheus underkänner två arbeten och ålägger ytterligare uppdrag.","status":"Textställe kontrollerat","kind":"Antik text i översättning"}],"related":["O082"]},"H005":{"topic":"Gilgamesheposets flodtavla","genre":"Fysiskt handskriftsbelägg","claim":"British Museum förvarar den nyassyriska flodtavlan K.3375, en del av Gilgamesheposets tavla XI.","limit":"Museiföremålet visar att denna litterära tradition fanns i antiken; en fysisk tavla är inte ett daterat belägg för en global flod.","passages":[{"reference":"Gilgamesheposet, tavla XI (K.3375)","label":"British Museum – The Flood Tablet","url":"https://www.britishmuseum.org/collection/search?keyword=K.3375","what":"Fysisk nyassyrisk lertavla med delar av flodberättelsen.","status":"Textställe kontrollerat","kind":"Antikt textvittne (museiföremål)"},{"reference":"Genesis 8:6–12","label":"Noa skickar ut fåglar","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D","what":"Den bibliska versionen ger en konkret motivparallell.","status":"Textställe kontrollerat","kind":"Bibeltext","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 8 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D"}]}],"related":["H020"]},"H020":{"topic":"Genesis urhistoria och äldre flodtraditioner","genre":"Bibeltext och antik texttradition","claim":"Genesis 6–9 kan jämföras på motivnivå med Gilgamesheposets flodavsnitt.","limit":"Likheter i fågelmotiv, fartyg och överlevnad ska diskuteras med skillnader i teologisk funktion och texttraditionernas utveckling.","passages":[{"reference":"Genesis 6–9, särskilt 8:6–12","label":"Noas flod och utsända fåglar","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D","what":"Bibeltext med flod, ark, vila och fågelmotiv.","status":"Textställe kontrollerat","kind":"Bibeltext","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 6 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.6.B2000D"},{"label":"Läs kapitel 7 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.7.B2000D"},{"label":"Läs kapitel 8 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D"},{"label":"Läs kapitel 9 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.9.B2000D"}]},{"reference":"Gilgamesh XI, tavlan K.3375","label":"Flodtavlan på British Museum","url":"https://www.britishmuseum.org/collection/search?keyword=K.3375","what":"Antikt textvittne för flodtraditionen.","status":"Textställe kontrollerat","kind":"Antikt textvittne (museiföremål)"}],"related":["H005"]}};
const textPairsV89=[{"id":"birds","theme":"Flodtraditioner","title":"Noa och Utnapishtim: fåglarna efter floden","subtitle":"Ett tydligt och ovanligt motivkomplex, men inte identiska texter.","assessment":"Stark motiv- och sekvenslikhet. Gemensam mesopotamisk berättartradition är en rimlig forskningsförklaring; direkt kopiering ur just den bevarade tavlan kan inte visas.","dependence":"Sannolikt traditionssamband; exakt överföringsväg okänd.","left":{"title":"Genesis / Första Moseboken","reference":"1 Mos 8:6–12","language":"Hebreiska","witness":"Bibeltext med kompositions- och redaktionshistoria","dating":"Textens tillkomst och slutliga redaktion omdiskuterade; skild från berättad urtid.","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D","status":"Textställe kontrollerat","post":"H020","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 8 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D"}]},"right":{"title":"Gilgamesheposet, tavla XI","reference":"XI:147–156","language":"Akkadiska","witness":"K.3375, kilskriftstavla från Ashurbanipals bibliotek, med parallellhandskrifter","dating":"K.3375: 600-talet f.Kr.; eposets tradition är äldre.","url":"https://www.soas.ac.uk/baplar/recordings/epic-gilgames-standard-version-tablet-xi-lines-1-163-read-karl-hecker","status":"Textställe kontrollerat","post":"H005"},"extra":[{"label":"Museiföremål K.3375 (British Museum)","url":"https://www.britishmuseum.org/collection/search?keyword=K.3375"}],"segments":[{"title":"Fåglarnas uppdrag","left":"Noa sänder ut korp och duva för att pröva om vattnet dragit sig tillbaka.","right":"Utnapishtim släpper först en duva, därefter en svala och till sist en korp.","similarity":"I båda berättelserna används fåglar för att undersöka land efter en förödande flod.","difference":"Ordningsföljden skiljer sig: Genesis börjar med korpen; Gilgamesh avslutar med korpen.","warning":"Fåglarna är ett starkt textmotiv, inte bevis för en historisk världsflod."},{"title":"Återkomst och utebliven återkomst","left":"Duvan återvänder först, senare med ett olivblad; vid tredje försöket återkommer den inte.","right":"Duvan och svalan återvänder utan viloplats; korpen finner förbättrade förhållanden och återvänder inte.","similarity":"Återkomst respektive utebliven återkomst ger information om landets tillstånd.","difference":"Olivbladet i Genesis har ingen direkt motsvarighet i dessa rader av Gilgamesh.","warning":"En textlig detaljlikhet måste skiljas från en ordagrann överensstämmelse."},{"title":"Textens vittnen","left":"Hebreisk bibeltext bevarad genom en lång handskriftstradition; berättelsens redaktionslager diskuteras.","right":"K.3375 är ett bevarat assyriskt textvittne från 600-talet f.Kr.; äldre babylonisk berättartradition finns.","similarity":"Båda kan undersökas textkritiskt genom bevarade vittnen.","difference":"Datering av handskriften är inte samma sak som ålder för motivet eller kompositionen.","warning":"Biblisk urtid kan inte dateras via det år då tavlan skrevs."}]},{"id":"sacrifice","theme":"Flodtraditioner","title":"Efter floden: offer och gudomlig reaktion","subtitle":"Liknande berättarstruktur, men olika gudsbilder.","assessment":"Stark tematisk jämförbarhet; teologiska skillnader är avgörande. Litterär miljö kan vara gemensam utan att varje detalj har samma innebörd.","dependence":"Traditionssamband möjligt och diskuterat; inte en likalydande text.","left":{"title":"Genesis / Första Moseboken","reference":"1 Mos 8:20–22","language":"Hebreiska","witness":"Den bibliska flodtraditionen","dating":"Den nuvarande textens tillkomst är omdiskuterad.","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D","status":"Textställe kontrollerat","post":"H020","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 8 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/GEN.8.B2000D"}]},"right":{"title":"Gilgamesheposet, tavla XI","reference":"XI:157–163","language":"Akkadiska","witness":"Standardbabylonisk text bevarad i assyrisk handskrift (bl.a. K.3375)","dating":"Bevarade tavlor från 600-talet f.Kr. och andra vittnen.","url":"https://www.soas.ac.uk/baplar/recordings/epic-gilgames-standard-version-tablet-xi-lines-1-163-read-karl-hecker","status":"Textställe kontrollerat","post":"H005"},"extra":[],"segments":[{"title":"Offer efter räddning","left":"Efter floden bygger Noa ett altare och offrar till Herren.","right":"Utnapishtim anordnar ett offer på berget efter att skeppet stannat och fåglarna prövats.","similarity":"Ett offer avslutar räddningen från floden i båda berättelserna.","difference":"Genesis rör en Gud; Gilgamesh låter flera gudar reagera.","warning":"Varken antal offer eller gudsbild bör likställas."},{"title":"Gudarnas/gudens reaktion","left":"Herren beslutar att inte på samma sätt förbanna marken igen och låter världens årstider fortgå.","right":"De mesopotamiska gudarna samlas kring den välkomna offerdoften.","similarity":"Offret följs av ett teologiskt avgörande i båda berättelserna.","difference":"Motiv och moralisk förklaring skiljer sig avsevärt; parallellen är inte en identisk teologi.","warning":"Parafrasen sammanfattar texten och är inte ett citat."}]},{"id":"law","theme":"Lag och rätt","title":"Öga för öga: Hammurabi och Exodus","subtitle":"Rättslig proportionalitet och sociala skillnader.","assessment":"Tydlig rättslig formellikhet, men inte ett självständigt bevis för direkt lån. Jämför även social status och andra fall i respektive lagmaterial.","dependence":"Gemensam forntida närorientalisk rättskultur; direkt härledning osäker.","left":{"title":"Hammurabis lagsamling","reference":"Lag §196","language":"Akkadiska","witness":"Dioritstelen i Louvren med lagsamling från Hammurabis regering","dating":"1700-talet f.Kr. (vanlig historisk kronologi).","url":"https://www.louvre.fr/en/the-code-of-hammurabi","status":"Textställe kontrollerat","post":"O079"},"right":{"title":"Första delen av Förbundsboken","reference":"2 Mos 21:23–25","language":"Hebreiska","witness":"Bibelns lagtext inom Exodus; tillkomstlager debatteras","dating":"Bibellagens komposition/redaktion kan inte dateras med ett enda säkert år.","url":"https://www.bible.com/sv/bible/417/EXO.21.B2000D","status":"Textställe kontrollerat","post":"H019","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 21 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/EXO.21.B2000D"}]},"extra":[],"segments":[{"title":"Proportionalitetsformeln","left":"§196 anger en kroppsskada (öga) och en motsvarande påföljd i ett samhälle där status kan påverka rättsföljden.","right":"Exodus 21:23–25 listar motsvarigheter som liv för liv, öga för öga och tand för tand.","similarity":"Båda använder en proportionalitetsprincip i juridiskt språk.","difference":"Texternas sociala sammanhang och behandling av olika personer är inte identiska.","warning":"Liknande rättsprincip kan förekomma utan att en bestämd text kopierats."},{"title":"Regel och rättslig kontext","left":"Hammurabis §§196–201 ger flera utfall beroende på vem som skadats.","right":"Exodus 21 behandlar bland annat våldsskador och ersättning i olika fall.","similarity":"Båda är delar av större samlingar av kasuistiska och normativa regler.","difference":"En enstaka fras räcker inte för att förstå lagens praktiska tillämpning.","warning":"Läs omgivande bestämmelser, inte endast formuleringen."}]},{"id":"mithras","theme":"Religionsritual","title":"Mithrasmåltiden och den kristna nattvarden","subtitle":"Ett sent partsreferat jämfört med en äldre kristen text.","assessment":"Ritlikhet på generell nivå: bröd och bägare. Ingen källa här belägger mithraisk berättelse om gudens död/uppståndelse eller att nattvarden uppstod genom kopiering.","dependence":"Direkt påverkan ej belagd; Justins vittnesmål är polemiskt.","left":{"title":"Justinus Martyren, Första apologin","reference":"Kapitel 66 (ca mitten av 100-talet e.Kr.)","language":"Grekiska","witness":"Kristen apologet som beskriver en mithraisk initiationsrit i polemik","dating":"Ca 150–160 e.Kr.","url":"https://www.newadvent.org/fathers/0126.htm","status":"Textställe kontrollerat","post":"O078"},"right":{"title":"Paulus första brev till Korinth","reference":"1 Kor 11:23–26","language":"Grekiska","witness":"Tidigt kristet brev om en gemenskapsmåltid","dating":"Ca 50-talet e.Kr. (vanlig forskningsdatering).","url":"https://www.bible.com/sv/bible/417/1CO.11.B2000D","status":"Textställe kontrollerat","post":"H030","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 11 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/1CO.11.B2000D"}]},"extra":[{"label":"Justinus på grekiska (Via Patrum)","url":"https://viapatrum.org/e/justin_1apol_66/"}],"segments":[{"title":"Bröd och bägare","left":"Justinus säger att bröd och en bägare vatten ställs fram vid initiationsriterna, med uttalade ord.","right":"Paulus förmedlar traditionen om bröd och en bägare knutna till Jesu minne.","similarity":"Bröd och bägare förekommer i två ritualskildringar.","difference":"Justinus berättar som kritisk kristen observatör, inte som invigd mithraisk författare; det är vatten, inte nödvändigtvis vin, han nämner om Mithras.","warning":"Justinus text är senare än Paulus brev och kan inte användas som belägg för en äldre mithraisk nattvard."},{"title":"Ritens innebörd","left":"Justinus hävdar att riten efterliknar den kristna.","right":"Paulus knyter måltiden till Jesu död och gemenskapens tillkännagivande.","similarity":"Båda beskrivningarna är religiöst meningsbärande.","difference":"De bakomliggande trosföreställningarna är inte visade som identiska i dessa källor.","warning":"Justinus anklagelse om imitation är hans värdering, inte oberoende verifierad historieskrivning."}]},{"id":"dumuzi","theme":"Sorg och myt","title":"Dumuzi och Tammuz: underjord och sorgekult","subtitle":"Namn- och kultsamband, men olika genrer.","assessment":"Tydligt traditionshistoriskt samband mellan Dumuzi/Tammuz, men de valda textställena beskriver olika moment. Ingen parallell till Jesu uppståndelse kan härledas ur dem.","dependence":"Namn-/kultsamband etablerat, specifikt litterärt beroende ej visat.","left":{"title":"Inannas nedstigning","reference":"ETCSL 1.4.1, rader 354–358","language":"Sumeriska","witness":"Komposittext i modern edition baserad på flera kilskriftvittnen","dating":"Bevarade vittnen framför allt från gammalbabylonisk tid, berättartraditionen äldre.","url":"https://etcsl.orinst.ox.ac.uk/cgi-bin/etcsl.cgi?text=t.1.4.1","status":"Textställe kontrollerat","post":"O074"},"right":{"title":"Hesekiels bok","reference":"Hes 8:14","language":"Hebreiska","witness":"Profettext som refererar till kvinnor som sörjer Tammuz","dating":"Berättad vision i exilens 500-tal f.Kr.; textredaktion diskuteras.","url":"https://www.bible.com/sv/bible/417/EZK.8.B2000D","status":"Textställe kontrollerat","post":"O074","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 8 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/EZK.8.B2000D"}]},"extra":[],"segments":[{"title":"Dumuzi överlämnas","left":"Inanna låter demonerna ta Dumuzi till underjordens makter.","right":"Hesekiel beskriver kvinnor som sörjer Tammuz vid tempelområdet.","similarity":"Dumuzi/Tammuz hör till samma mesopotamiska traditionskomplex.","difference":"Första texten är mytologisk berättelse; andra är en profetisk skildring av ett rituellt uttryck.","warning":"Hesekiel redogör inte för hela myten, och anger ingen uppståndelseberättelse."},{"title":"Textkällornas karaktär","left":"ETCSL-utgåvan rekonstruerar en sumerisk text från fragment och flera vittnen.","right":"Hesekiel är bevarad i en hebreisk bibeltext med egen redaktionshistoria.","similarity":"Båda ger historisk åtkomst till en traditionsmiljö.","difference":"De är olika typer av källor och ska inte vägas som om de berättade samma händelse.","warning":"Modern kompositutgåva är inte identisk med en enskild originaltavla."}]},{"id":"amenemope","theme":"Vishetslitteratur","title":"Egyptisk vishet och Ordspråksboken","subtitle":"Paralleller är viktiga men primärtextlokatorerna behöver ytterligare granskning.","assessment":"Omfattande forskningsdiskussion om litterär relation mellan Amenemope och Ords 22:17–23:11. Här visas vissa gemensamma teman, inte en verifierad ordagrann återgivning.","dependence":"Litterär relation föreslagen; omfång och överföringsväg omdiskuterade.","left":{"title":"Amenemopes undervisning","reference":"Texten som helhet; särskilda parallellrader återstår att verifiera","language":"Egyptiska","witness":"Papyrus British Museum EA 10474 är ett centralt textvittne","dating":"Datering av komposition och papyrusvittne skiljer sig; båda diskuteras.","url":"https://www.britishmuseum.org/collection/search?keyword=EA%2010474","status":"Källvittne belagt; radlokator kräver kontroll","post":"O090"},"right":{"title":"Ordspråksboken – de visas ord","reference":"Ords 22:17–23:11, särskilt 22:22–23","language":"Hebreiska","witness":"Bibelns vishetssamling med flera litterära lager","dating":"Komposition och samlingsredaktion har skett i flera faser.","url":"https://www.bible.com/sv/bible/417/PRO.22.B2000D","status":"Textställe kontrollerat","post":"H019","bibleTranslation":"Bibel 2000 (B2000D) · svenska","bible2000Links":[{"label":"Läs kapitel 22 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/PRO.22.B2000D"},{"label":"Läs kapitel 23 i Bibel 2000","url":"https://www.bible.com/sv/bible/417/PRO.23.B2000D"}]},"extra":[],"segments":[{"title":"De fattigas rätt","left":"Den egyptiska vishetstraditionen varnar bland annat för att utnyttja svaga; exakt kapitel/rad kräver kontroll mot kritisk utgåva.","right":"Ords 22:22–23 förbjuder att plundra fattiga och förtrycka nödställda.","similarity":"Rättvisa gentemot utsatta är ett gemensamt vishetsmotiv.","difference":"Egyptisk parallell ska inte framställas som ett ordagrant citat utan kontrollerad primärutgåva.","warning":"Textlokator på egyptisk sida är preliminär."},{"title":"Undervisningens form","left":"Amenemope är ordnad som ett längre undervisningsverk med trettio kapitel.","right":"Ords 22:17 inleder en serie vishetsord; ordalydelsen i 22:20 är omdiskuterad (bl.a. ”trettio”).","similarity":"Samlingar av pedagogiska råd och möjligen formella paralleller.","difference":"Likheter i antal och disposition är omdiskuterade och räcker inte ensamma för att belägga lån.","warning":"Här visas referat och forskningsstatus, inte ordagrann text."}]}];
